text:
{
 "lead": {
  "es": "令和《れいわ》8年《ねん》にひらかれる愛知《あいち》・名古屋《なごや》アジア競技大会《きょうぎたいかい》と愛知《あいち》・名古屋《なごや》アジアパラ競技大会《きょうぎたいかい》についての法律《ほうりつ》です。かかるお金《かね》をへらしながら、会場《かいじょう》などのしせつの警備《けいび》や暑《あつ》さへの対策《たいさく》などをしっかり行《おこな》うため、とくべつなきまりを定《さだ》めます。",
  "hs": "令和8年に開かれる愛知・名古屋アジア競技大会と愛知・名古屋アジアパラ競技大会についての法律です。経費の削減《さくげん》などを図りながら、施設《しせつ》の警備や暑さ対策などに万全を期すため、必要な特別措置《とくべつそち》（特別なきまり）を定めます。"
 },
 "facts/0/text": {
  "es": "国《くに》は、公益財団法人《こうえきざいだんほうじん》愛知《あいち》・名古屋《なごや》アジア・アジアパラ競技大会組織委員会《きょうぎたいかいそしきいいんかい》に、大会《たいかい》の準備《じゅんび》や運営《うんえい》にかかるお金《かね》の一部《いちぶ》を、予算《よさん》の中《なか》で出《だ》す（補助《ほじょ》する）ことができます。",
  "hs": "国は、公益財団法人愛知・名古屋アジア・アジアパラ競技大会組織委員会に対し、大会の準備や運営の費用の一部を、予算の範囲《はんい》内で補助できます。"
 },
 "facts/1/text": {
  "es": "お年玉《としだま》付《つき》郵便葉書《ゆうびんはがき》等《とう》に関《かん》する法律《ほうりつ》で決《き》められた、寄附金《きふきん》（ある目的《もくてき》のために出《だ》すお金《かね》）のついた郵便《ゆうびん》はがきなどを発行《はっこう》できます。その寄附金《きふきん》は、組織委員会《そしきいいんかい》が集《あつ》める、大会《たいかい》の準備《じゅんび》や運営《うんえい》のお金《かね》にあてます。",
  "hs": "お年玉付郵便葉書等に関する法律で決められた寄附金《きふきん》付きの郵便はがきなどを、組織委員会が集める大会の準備・運営の資金にあてる目的で発行できます。"
 },
 "facts/2/text": {
  "es": "組織委員会《そしきいいんかい》には、無線局《むせんきょく》（電波《でんぱ》を使《つか》う通信《つうしん》のしせつ）の免許《めんきょ》（使《つか》ってよいというゆるし）や登録《とうろく》を申《もう》しこむときの手数料《てすうりょう》と、無線局《むせんきょく》の電波利用料《でんぱりようりょう》について、電波法《でんぱほう》のきまりを当《あ》てはめません。",
  "hs": "組織委員会については、無線局の免許《めんきょ》・登録の申請《しんせい》などの手数料と、無線局の電波利用料について、電波法の規定を当てはめないことにします。"
 },
 "facts/3/text": {
  "es": "この法律《ほうりつ》は、公布《こうふ》（世《よ》の中《なか》に広《ひろ》く知《し》らせること）された日《ひ》から使《つか》われます。",
  "hs": "この法律は、公布（世の中に知らせること）の日から使われ始めます。"
 },
 "more/reason/text": {
  "es": "この法律案《ほうりつあん》を出《だ》した側《がわ》は、次《つぎ》のように説明《せつめい》している。令和《れいわ》8年《ねん》にひらかれる愛知《あいち》・名古屋《なごや》アジア競技大会《きょうぎたいかい》と愛知《あいち》・名古屋《なごや》アジアパラ競技大会《きょうぎたいかい》は、大《おお》きく、国《くに》にとって大事《だいじ》なスポーツ大会《たいかい》である。世《よ》の中《なか》の急《きゅう》な変化《へんか》に、かかるお金《かね》をへらしながら対応《たいおう》する必要《ひつよう》がある。大会《たいかい》をなめらかに、安全《あんぜん》に進《すす》めるため、しせつの警備《けいび》や暑《あつ》さへの対策《たいさく》などに、しっかり取《と》り組《く》む必要《ひつよう》があるためとしている。",
  "hs": "この法律案を提出した側は、令和8年に開かれる愛知・名古屋アジア競技大会と愛知・名古屋アジアパラ競技大会が、大規模で国家的に重要なスポーツの競技会であるためとしている。社会経済情勢の急な変化に、経費の削減《さくげん》などを図りつつ対応する必要があるとしている。また、大会を円滑《えんかつ》（スムーズ）かつ安全に行うため、施設《しせつ》の警備や暑熱（暑さ）に関する対策などに万全を期する必要があるとしている。"
 },
 "more/who/text": {
  "es": "大会《たいかい》の準備《じゅんび》と運営《うんえい》をする、公益財団法人《こうえきざいだんほうじん》愛知《あいち》・名古屋《なごや》アジア・アジアパラ競技大会組織委員会《きょうぎたいかいそしきいいんかい》（国《くに》からお金《かね》の一部《いちぶ》を出《だ》してもらえる。無線局《むせんきょく》の手数料《てすうりょう》と電波利用料《でんぱりようりょう》について、電波法《でんぱほう》のきまりが当《あ》てはまらなくなる）",
  "hs": "大会の準備と運営をする公益財団法人愛知・名古屋アジア・アジアパラ競技大会組織委員会（国による経費の補助の対象となり、無線局の手数料・電波利用料についての電波法の規定が当てはまらなくなる）"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》では、文部科学委員会《もんぶかがくいいんかい》が、内閣《ないかく》の意見《いけん》を聞《き》いたあと、賛成《さんせい》が多《おお》く、委員会《いいんかい》からこの法律案《ほうりつあん》を出《だ》すことを決《き》めた。この大会《たいかい》についての決議《けつぎ》（委員会《いいんかい》としての考《かんが》え）もおこなった。参議院《さんぎいん》の文教科学委員会《ぶんきょうかがくいいんかい》では、これまで日本《にほん》で開《ひら》かれた国際《こくさい》スポーツ大会《たいかい》などの、とくべつなきまりの法律《ほうりつ》とくらべることについて質問《しつもん》があった。組織委員会《そしきいいんかい》と、大会《たいかい》を開《ひら》く自治体《じちたい》（県《けん》や市《し》）の説明《せつめい》の責任《せきにん》などについても質問《しつもん》があった。賛成《さんせい》が多《おお》く、もとの案《あん》のまま可決《かけつ》した。",
  "hs": "衆議院では、文部科学委員会が内閣の意見を聞いたあと、賛成多数で委員会提出の法律案とすることを決め、大会に関する決議も行った。参議院の文教科学委員会では、過去に国内で開かれた国際スポーツ大会などの特別措置法《とくべつそちほう》との比較《ひかく》や、組織委員会と開催《かいさい》自治体の説明責任などについて質疑があった。採決では、賛成多数で原案のとおり可決した。"
 }
}
